import Foundation

// Offline URLProtocol-backed integration of Python-signed v2 metadata.
// Requires a fixture directory generated by generate-zag-v2-python-fixture.py.
final class FixtureURLProtocol: URLProtocol {
    static var responseData = Data()
    static var responseStatus = 200
    override class func canInit(with request: URLRequest) -> Bool { true }
    override class func canonicalRequest(for request: URLRequest) -> URLRequest { request }
    override func startLoading() {
        let response = HTTPURLResponse(
            url: request.url!, statusCode: Self.responseStatus,
            httpVersion: "HTTP/1.1", headerFields: ["Content-Type": "application/json"]
        )!
        client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
        client?.urlProtocol(self, didLoad: Self.responseData)
        client?.urlProtocolDidFinishLoading(self)
    }
    override func stopLoading() {}
}

@main
struct V2DiscoveryIntegrationTests {
    static func main() async throws {
        guard CommandLine.arguments.count == 2 else {
            fputs("Usage: test-zag-v2-discovery-integration <fixture-dir>\n", stderr)
            exit(2)
        }
        let directory = URL(fileURLWithPath: CommandLine.arguments[1], isDirectory: true)
        let signed = try Data(contentsOf: directory.appendingPathComponent("envelope.json"))
        let publicKey = try Data(contentsOf: directory.appendingPathComponent("public-key.raw"))
        let url = URL(string: "https://raw.githubusercontent.com/zagorskey/zag-store-releases/main/releases/beta.v2.json")!
        let now = ISO8601DateFormatter().date(from: "2026-10-17T12:00:00Z")!
        let config = URLSessionConfiguration.ephemeral
        config.protocolClasses = [FixtureURLProtocol.self]
        let session = URLSession(configuration: config)
        defer { session.invalidateAndCancel() }
        let service = "app.zagstore.ios.discovery-integration.\(UUID().uuidString)"
        let store = ZagUpdateRollbackStore(service: service)
        defer {
            let query: [String: Any] = [
                kSecClass as String: kSecClassGenericPassword,
                kSecAttrService as String: service
            ]
            _ = SecItemDelete(query as CFDictionary)
        }
        let keys = ["disposable-python-jcs": publicKey]
        func fetch() async throws -> ZagUpdateMetadataV2.Payload {
            try await ZagUpdateV2Discovery.fetchVerified(
                from: url, channel: "beta", trustedKeys: keys,
                store: store, session: session, now: now
            )
        }
        FixtureURLProtocol.responseData = signed
        FixtureURLProtocol.responseStatus = 200
        let accepted = try await fetch()
        guard accepted.sequence == 11,
              accepted.releaseNotes == "Обновяване — Café ☕ 日本語 🔐",
              try await store.highestAccepted(channel: "beta") == 11 else {
            fatalError("Valid signed fixture mismatch")
        }
        print("PASS: mocked HTTPS response accepted signed Python Unicode metadata")

        FixtureURLProtocol.responseStatus = 404
        do {
            _ = try await fetch()
            print("FAIL: HTTP 404 accepted")
            exit(1)
        } catch ZagUpdateV2Discovery.DiscoveryError.httpStatus(404) {
            print("PASS: HTTP 404 rejected")
        }
        FixtureURLProtocol.responseStatus = 200
        FixtureURLProtocol.responseData = Data(repeating: 0x20, count: ZagUpdateV2Discovery.maximumEnvelopeBytes + 1)
        do {
            _ = try await fetch()
            print("FAIL: oversized response accepted")
            exit(1)
        } catch ZagUpdateV2Discovery.DiscoveryError.oversizedResponse {
            print("PASS: oversized response rejected")
        }
        guard try await store.highestAccepted(channel: "beta") == 11 else {
            fatalError("Rejected responses modified rollback state")
        }
        print("PASS: rejected HTTP responses preserved rollback state")
        print("SUCCESS: offline v2 discovery integration passed")
    }
}
